L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Talk_KOREA = "어릴 때, 숲에 들어갔다가 굶주린 곰이랑 마주친 적이 있었어."
L2_1.m_fTalkTime = 0.03
L2_1.m_bTalkCenterFadeIn = true
L2_1.m_Talk_JPN = "小さい頃、森に入って飢えたクマと遭遇したことがあった。"
L2_1.m_Talk_ENG = "When I was young, I went into the woods and ran into a starving bear."
L2_1.m_Talk_TWN = "小時候去森林裡玩，我遇到了饑餓的熊。"
L2_1.m_Talk_THA = "ตอนยังเด็ก ผมเคยเข้าป่าแล้วบังเอิญเจอหมีหิวโซเข้า"
L2_1.m_Talk_VTN = "Khi còn nhỏ, tôi đã đi lạc vào rừng và gặp một con gấu đang đói khát."
L2_1.m_Talk_SCN = "小时候去森林里玩，我遇到了饥饿的熊。"
L2_1.m_Talk_DEU = "Als ich jung war, ging ich in den Wald und begegnete einem hungrigen Bären."
L2_1.m_Talk_FRA = "Un jour, quand j'étais jeune, je suis tombé sur un ours affamé alors que je m'étais perdu dans les bois."
L3_1 = {}
L3_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE3@3#Talk"
L3_1.m_CutScenProcessKey = 3
L3_1.m_CutScenID = 425
L3_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Talk_KOREA = "신기하게도 하나도 무섭지 않았어."
L3_1.m_fTalkTime = 0.03
L3_1.m_bTalkCenterFadeIn = true
L3_1.m_Talk_JPN = "でも不思議なことに、ひとつも怖くなかった。"
L3_1.m_Talk_ENG = "Strange as it is, I wasn't frightened at all."
L3_1.m_Talk_TWN = "神奇的是我一點都不害怕。"
L3_1.m_Talk_THA = "แต่แปลก ผมไม่กลัวเลยสักนิดเดียว"
L3_1.m_Talk_VTN = "Thật kỳ lạ, tôi không sợ hãi chút nào."
L3_1.m_Talk_SCN = "神奇的是我一点都不害怕。"
L3_1.m_Talk_DEU = "Seltsamerweise hatte ich überhaupt keine Angst."
L3_1.m_Talk_FRA = "Pourtant, aussi étrange que cela puisse paraître, je n'avais pas peur du tout."
