L6_1.m_Crash = 15
L6_1.m_Talk_KOREA = "이, 이쪽으로 온다!!"
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "む、向かってくるぞ！！"
L6_1.m_Talk_ENG = "H-he’s coming this way!"
L6_1.m_Talk_TWN = "往，往這邊來了！！"
L6_1.m_Talk_THA = "มะ-มันกำลังมาทางนี้แล้ว!"
L6_1.m_Talk_VTN = "H-hắn đang tiến về bên này!"
L6_1.m_Talk_SCN = "往、往这边来了！！"
L6_1.m_Talk_DEU = "E-er kommt auf uns zu!!"
L6_1.m_Talk_FRA = "I-Il vient par ici !"
L7_1 = {}
L7_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE3@7#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 425
L7_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "KNIGHT_NPC_NULL_NULL"
L7_1.m_Pos = "R"
L7_1.m_Crash = 30
L7_1.m_Talk_KOREA = "대체 저 괴물은 뭐야! 혼자서 싸우는데 왜 상처 하나 입지 않냐고!!"
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "なんだあの化け物は！　たった一人で戦っているというのに、なんで傷ひとつ付かないんだ！！"
L7_1.m_Talk_ENG = "What is that monster?! He’s fighting alone, how is he unscathed?!"
L7_1.m_Talk_TWN = "那個怪物究竟是什麼東西！為什麼明明孤身一人，卻還是毫髮無傷！！"
L7_1.m_Talk_THA = "ไอ้สัตว์ประหลาดนั่นมันอะไร?! สู่อยู่ตัวเดียวแต่ไม่มีรอยขีดข่วนเลย?!"
L7_1.m_Talk_VTN = "Quái vật gì vậy?! Hắn vẫn chiến đấu một mình, sao hắn không hề hấn gì chứ?!"
L7_1.m_Talk_SCN = "那个怪物究竟是什么东西！为什么明明只有一个人，却什么都伤不到他！！"
L7_1.m_Talk_DEU = "Was zum Teufel ist das für ein Monster?! Warum hat er nicht einen einzigen Kratzer, obwohl er ganz allein kämpft?!"
L7_1.m_Talk_FRA = "C'est quoi, ce monstre ? Il se bat tout seul contre une armée, et il n'a pas une égratignure ?"
L8_1 = {}
L8_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE3@8#Talk"
L8_1.m_CutScenProcessKey = 8
L8_1.m_CutScenID = 425
L8_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "KNIGHT_NPC_NULL_NULL"
L8_1.m_Pos = "L"
L8_1.m_Crash = 20
L8_1.m_Talk_KOREA = "구원자님! 어디 계십니까! 구원자님!!"
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "救世主様！　どこですか！　救世主様！！"
L8_1.m_Talk_ENG = "Savior! Where are you, Savior?!"
L8_1.m_Talk_TWN = "救贖者大人！您在哪裡！救贖者大人！！"
L8_1.m_Talk_THA = "พระผู้ไถ่! ท่านอยู่ที่ไหน พระผู้ไถ่?!"
L8_1.m_Talk_VTN = "Đấng Cứu Thế! Ngài ở đâu, hỡi Đấng Cứu Thế?"
L8_1.m_Talk_SCN = "救赎者！您在哪里！救赎者！！"
L8_1.m_Talk_DEU = "Erlöser! Wo bist du, Erlöser?!"
L8_1.m_Talk_FRA = "Sauveur ! Où êtes-vous, Sauveur ?!"
