L12_1 = {}
L12_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE3@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 425
L12_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Talk_KOREA = "기억해 보면 예전부터 그랬어."
L12_1.m_fTalkTime = 0.03
L12_1.m_bTalkCenterFadeIn = true
L12_1.m_Talk_JPN = "思い返せば、昔からそうだった。"
L12_1.m_Talk_ENG = "I think it's always been like that."
L12_1.m_Talk_TWN = "仔細想想，從以前開始就一直如此。"
L12_1.m_Talk_THA = "ผมคิดว่ามันจะเป็นเช่นนั้นเสมอ"
L12_1.m_Talk_VTN = "Tôi nghĩ luôn là như vậy."
L12_1.m_Talk_SCN = "仔细想想，从以前开始就一直如此。"
L12_1.m_Talk_DEU = "Ich denke, es war schon immer so."
L12_1.m_Talk_FRA = "Quand j'y pense, ça a toujours été comme ça."
L13_1 = {}
L13_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE3@13#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 425
L13_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Talk_KOREA = "칼을 들고 있으면 사나운 짐승도, 어떤 괴물도 무섭지 않았거든."
L13_1.m_fTalkTime = 0.03
L13_1.m_bTalkCenterFadeIn = true
L13_1.m_Talk_JPN = "剣さえあれば、狂暴な獣も、どんな怪物も怖くなかった。"
L13_1.m_Talk_ENG = "With a sword in my hand, no beast or monster could ever frighten me."
L13_1.m_Talk_TWN = "只要我手中有劍，不管是猛獸還是怪物，我便都不會害怕。"
L13_1.m_Talk_THA = "ขอเพียงมีดาบในมือ จะสัตว์ร้ายหรือสัตว์ประหลาดหน้าไหน ผมก็ไม่กลัว"
L13_1.m_Talk_VTN = "Với thanh kiếm trong tay, tôi không sợ hãi trước bất kỳ con quái vật hay quái thú nào."
L13_1.m_Talk_SCN = "只要我手中有剑，不管是猛兽还是怪物，我便都不会害怕。"
L13_1.m_Talk_DEU = "Solange ich ein Schwert in der Hand hielt, verspürte ich keine Angst. Weder vor wilden Tieren noch vor irgendwelchen Monstern."
L13_1.m_Talk_FRA = "Avec une épée dans la main aucun monstre, aucune bête ne m'a jamais fait peur."
L14_1 = {}
L14_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE3@14#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 425
L14_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Talk_KOREA = "알렌은 그걸 타고난 본능 때문이라고 가르쳐 줬어."
L14_1.m_fTalkTime = 0.03
L14_1.m_bTalkCenterFadeIn = true
L14_1.m_Talk_JPN = "アレンは、それは生まれつきの本能のせいだと教えてくれた。"
L14_1.m_Talk_ENG = "Allen told me that I was born with certain instincts."
L14_1.m_Talk_TWN = "艾倫說這是與生俱來的本能。"
L14_1.m_Talk_THA = "อัลเลนบอกว่าผมเกิดมาพร้อมสัญชาตญาณบางอย่าง"
L14_1.m_Talk_VTN = "Allen đã nói rằng bản thân tôi tiềm ẩn những bản năng nhất định."
L14_1.m_Talk_SCN = "艾伦说这是与生俱来的本能。"
L14_1.m_Talk_DEU = "Allen sagte mir, dass ich mit einem bestimmten Instinkt geboren wurde."
L14_1.m_Talk_FRA = "Allen disait que j'étais né avec un don naturel."
L15_1 = {}
L15_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE3@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 425
L15_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Talk_KOREA = "넌 칼을 들고 있는 동안에는, 상대를 이길 수 있을지 없을지 직감적으로 알아챈다면서."
L15_1.m_fTalkTime = 0.03
L15_1.m_bTalkCenterFadeIn = true
L15_1.m_Talk_JPN = "僕は剣を持っている間は、相手に勝てるかどうかが直感的にわかっしまうと。"
L15_1.m_Talk_ENG = "That, while holding a sword, I instinctively know whether I can beat the enemy or not."
L15_1.m_Talk_TWN = "他還說我拿著劍的時候，直覺上就會知道是否能夠戰勝對手。"
L15_1.m_Talk_THA = "ว่าแค่ผมถือดาบอยู่ ก็จะรู้ได้โดยสัญชาตญาณว่าตัวเองจะเอาชนะศัตรูได้หรือไม่"
L15_1.m_Talk_VTN = "Rằng, khi cầm kiếm, bản năng khiến tôi hiểu mình có thể đánh bại kẻ thù hay không."
L15_1.m_Talk_SCN = "他还说我拿着剑的时候，直觉上就会知道是否能够战胜对手。"
L15_1.m_Talk_DEU = "Dass ich, wenn ich ein Schwert in der Hand halte, instinktiv weiß, ob ich den Feind besiegen kann oder nicht."
L15_1.m_Talk_FRA = "Un instinct qui me disait tout de suite si j'étais en mesure de vaincre mon adversaire ou non."
