L17_1 = {}
L17_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE3@17#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 425
L17_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Talk_KOREA = "산개해! 비공정이 추락한다!"
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "散開しろ！　飛行艇が落ちてくるぞ！"
L17_1.m_Talk_ENG = "Disassemble! The aircraft is crashing!"
L17_1.m_Talk_TWN = "散開！飛空艇要墜落了！"
L17_1.m_Talk_THA = "กระจายกำลัง! อากาศยานกำลังตกแล้ว!"
L17_1.m_Talk_VTN = "Giải tán! Máy bay đang rơi xuống!"
L17_1.m_Talk_SCN = "散开！飞空艇要坠落了！"
L17_1.m_Talk_DEU = "Verteilt euch! Das Flugzeug stürzt ab!"
L17_1.m_Talk_FRA = "Le vaisseau s'écrase ! Courez !"
L18_1 = {}
L18_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE3@18#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 425
L18_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_BGCrash = 30
L18_1.m_fBGCrashTime = 1
L18_1.m_StartFXSoundName = "FX_COMBAT_ALL_HIT_ROCK_BIG_02"
L18_1.m_Talk_KOREA = "골렘도 전멸했어! 이제 끝이야……! 끝이라고!!"
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "ゴーレムも全滅だ！　もう終わりだ……！　おしまいだ！！"
L18_1.m_Talk_ENG = "All golems down! We're done for... We’re doomed!"
L18_1.m_Talk_TWN = "泥人也全軍覆沒了！現在完了……！完了！！"
L18_1.m_Talk_THA = "โกเลมแพ้หมดทุกตัว! เราจบเห่แล้ว... บรรลัยสิ้น!"
L18_1.m_Talk_VTN = "Tất cả golem hãy lùi xuống! Chúng ta xong rồi...tiêu đời rồi!"
L18_1.m_Talk_SCN = "魔像也全军覆没了！现在完了……！完了！！"
L18_1.m_Talk_DEU = "Alle Golems wurden erledigt! Es ist vorbei ... Wir sind geliefert!"
L18_1.m_Talk_FRA = "Tous les golems sont à terre ! Nous sommes perdus !"
L19_1 = {}
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 425
L19_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
