L20_1 = {}
L20_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE3@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 425
L20_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Talk_KOREA = "내게는 필요없는 힘이었지만, 적어도 누군가를 지키는 데 쓸 수는 있었어."
L20_1.m_fTalkTime = 0.03
L20_1.m_bTalkCenterFadeIn = true
L20_1.m_Talk_JPN = "僕には必要ない力だったけど、この力で少なくとも誰かを守ることはできた。"
L20_1.m_Talk_ENG = "I didn't need that power, but I could at least use it to protect others."
L20_1.m_Talk_TWN = "雖然我不需要這樣的力量，但至少我可以用它來保護某個人。"
L20_1.m_Talk_THA = "ผมไม่ได้อยากได้พลังนั่น แต่อย่างน้อยก็ใช้ปกป้องคนอื่นได้"
L20_1.m_Talk_VTN = "Vốn dĩ tôi không cần sức mạnh đó, nhưng ít ra nó có thể giúp tôi bảo vệ những người khác."
L20_1.m_Talk_SCN = "虽然我不需要这样的力量，但至少我可以用它来保护某个人。"
L20_1.m_Talk_DEU = "Ich brauchte diese Kraft zwar nicht, aber ich konnte sie zumindest nutzen, um andere zu beschützen."
L20_1.m_Talk_FRA = "Ce pouvoir ne m'était pas vraiment utile mais au moins, il pouvait m'aider à protéger les autres."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE3@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 425
L21_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Talk_KOREA = "그래서 구원자가 되어 사람들을 지키겠다고 결심했지만……."
L21_1.m_fTalkTime = 0.03
L21_1.m_bTalkCenterFadeIn = true
L21_1.m_Talk_JPN = "だから救世主になって、みんなを守るって決めたのに……"
L21_1.m_Talk_ENG = "Hence, I decided to be the Savior, to protect everyone..."
L21_1.m_Talk_TWN = "所以我才下定了決心，成為保護人們的救贖者……"
L21_1.m_Talk_THA = "เพราะฉะนั้น ผมเลยตัดสินใจจะเป็นพระผู้ไถ่ เพื่อปกป้องทุกคน..."
L21_1.m_Talk_VTN = "Vì vậy, tôi đã quyết định trở thành Đấng Cứu Thế để bảo vệ mọi người."
L21_1.m_Talk_SCN = "所以我才下定了决心，成为保护人们的救赎者……"
L21_1.m_Talk_DEU = "Also beschloss ich, der Erlöser zu werden, um die Menschen zu beschützen, aber ..."
L21_1.m_Talk_FRA = "C'est pourquoi j'ai décidé d'endosser le rôle du Sauveur. Pour protéger ce monde..."
