L28_1.m_Pos = "R"
L28_1.m_Crash = 10
L28_1.m_Talk_KOREA = "정신이 들었나……. 현자의 비약을 남겨 두길 다행이군."
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "意識が戻ったか……賢者の秘薬を残しておいたのが幸いだった。"
L28_1.m_Talk_ENG = "You're awake... It was a wise decision to save up on the Sage's potions..."
L28_1.m_Talk_TWN = "你醒了……幸虧智者的秘藥還有剩。"
L28_1.m_Talk_THA = "ฟื้นแล้วสินะ... ตัดสินใจถูกจริงๆ ที่เก็บยาของท่านนักปราชญ์เอาไว้"
L28_1.m_Talk_VTN = "Cậu đã tỉnh rồi... Thật sáng suốt khi giữ lại chút thuốc của Hiền Nhân..."
L28_1.m_Talk_SCN = "你醒了……幸亏贤者的秘药还有剩。"
L28_1.m_Talk_DEU = "Du bist aufgewacht ... Es war eine kluge Entscheidung, ein wenig von den Zaubertränken des Weisen aufzuheben ..."
L28_1.m_Talk_FRA = "Tu es réveillé... ? J'ai bien fait de garder des élixirs du Sage."
L29_1 = {}
L29_1.m_CutScenKey_Talk = "EP10_ACT1_INTERLUDE3@29#Talk"
L29_1.m_CutScenProcessKey = 29
L29_1.m_CutScenID = 425
