L29_1.m_Pos = "L"
L29_1.m_Talk_KOREA = "알렌, 등에 피가 이렇게나 많이……."
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "アレン、背中に血がこんなに……"
L29_1.m_Talk_ENG = "Allen, there's so much blood on your back..."
L29_1.m_Talk_TWN = "艾倫，你的後背流了很多血……"
L29_1.m_Talk_THA = "อัลเลนครับ หลังคุณเลือดเต็มเลย..."
L29_1.m_Talk_VTN = "Allen, lưng anh chảy nhiều máu quá..."
L29_1.m_Talk_SCN = "艾伦，你的后背流了很多血……"
L29_1.m_Talk_DEU = "Allen, es klebt so viel Blut an deinem Rücken ..."
L30_1 = "Allen... ton dos, tu... tout ce sang..."
L29_1.m_Talk_FRA = L30_1
