L31_1 = "내가 얼마나 쓰러져 있었던 거야? 마왕과 검을 맞댄 다음에 분명……."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "僕はどのくらい倒れてたの？　魔王と剣を交えて、そのあとは確か……"
L30_1.m_Talk_JPN = L31_1
L31_1 = "How long was I out? I remember crossing blades with the Demon Lord, then..."
L30_1.m_Talk_ENG = L31_1
L31_1 = "我暈倒多久了？在與魔王的劍碰上之後，我明明……"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ผมสลบไปนานแค่ไหนครับ? ผมจำได้ว่าประดาบกับเจ้าแห่งดีม่อน แล้วก็..."
L30_1.m_Talk_THA = L31_1
L31_1 = "Tôi ngất bao lâu rồi? Tôi nhớ mình đang đọ kiếm với Chúa Quỷ, sau đó..."
L30_1.m_Talk_VTN = L31_1
L31_1 = "我晕倒多久了？在与魔王的剑碰上之后，我明明……"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Wie lange war ich bewusstlos? Ich erinnere mich noch daran, dass ich mit dem Dämonenfürsten die Klinge gekreuzt habe ..."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Qu'est-ce qui s'est passé ? Je me souviens seulement d'avoir croisé le fer avec le Seigneur démon et..."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP10_ACT1_INTERLUDE3@31#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 31
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 425
L31_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
