L31_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L31_1.m_Pos = "R"
L32_1 = "미안하지만, 설명할 시간이 없어."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "悪いが、説明している暇はない。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "I'm sorry, but there's no time to explain."
L31_1.m_Talk_ENG = L32_1
L32_1 = "對不起，沒時間跟你解釋了。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ขอโทษนะ แต่ไม่มีเวลาอธิบายแล้ว"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tôi xin lỗi, nhưng không có thời gian để giải thích đâu."
L31_1.m_Talk_VTN = L32_1
L32_1 = "对不起，没时间跟你解释了。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Es tut mir leid, aber wir haben keine Zeit für Erklärungen."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Désolé, mais je n'ai pas le temps de t'expliquer."
L31_1.m_Talk_FRA = L32_1
