L33_1 = "나는, 괜찮으니까…… 전하를……"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "私は、大丈夫だ……それよりも殿下を……"
L32_1.m_Talk_JPN = L33_1
L33_1 = "I'll be fine... Take care of His Highness..."
L32_1.m_Talk_ENG = L33_1
L33_1 = "我，沒關係……保護殿下……"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ผมไม่เป็นไรหรอก... ดูแลฝ่าบาท..."
L32_1.m_Talk_THA = L33_1
L33_1 = "Tôi sẽ ổn thôi... Hãy chăm sóc Điện Hạ..."
L32_1.m_Talk_VTN = L33_1
L33_1 = "我，没关系……保护殿下……"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Mir geht es gut, also ... Kümmere dich um Seine Hoheit ..."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Ne t'en fais pas pour moi... Son Altesse, tu dois..."
L32_1.m_Talk_FRA = L33_1
