L35_1.m_Pos = "C"
L35_1.m_Crash = 20
L36_1 = "알렌! 내 말 들려, 알렌?! 어서 대답해!!"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "アレン！　聞こえる、アレン！？　返事して！！"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Allen! Can you hear me, Allen? Answer me!"
L35_1.m_Talk_ENG = L36_1
L36_1 = "艾倫！你能聽見我說話嗎，艾倫？！回答我！！"
L35_1.m_Talk_TWN = L36_1
L36_1 = "อัลเลน! ได้ยินผมมั้ย? ตอบสิครับ!"
L35_1.m_Talk_THA = L36_1
L36_1 = "Allen! Anh có nghe thấy tôi nói không, Allen? Trả lời tôi đi!"
L35_1.m_Talk_VTN = L36_1
L36_1 = "艾伦！你能听见我说话吗，艾伦？！回答我！！"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Allen! Kannst du mich hören, Allen? Antworte mir!"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Allen ! Tu m'entends, Allen ! Réponds-moi !"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP10_ACT1_INTERLUDE3@36#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 36
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 425
L36_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "UNIT_SERIOUS"
L36_1.m_Face = L37_1
L37_1 = "PRINCE_KNIGHT_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "뭐 하고 있나! 고개를 들어라, 평민!"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "何をしている！　顔を上げろ、平民！"
L36_1.m_Talk_JPN = L37_1
L37_1 = "What do you think you're doing? Put your head up, peasant!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "你在幹什麼！抬起頭來，平民！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "นี่เจ้าคิดว่าตนกำลังทำอะไรอยู่? เงยหน้าขึ้นมาสิ เจ้าไพร่!"
L36_1.m_Talk_THA = L37_1
L37_1 = "Cậu nghĩ mình đang làm gì thế? Ngẩng cao đầu lên, Nhóc Nông Dân!"
L36_1.m_Talk_VTN = L37_1
L37_1 = "你在干什么！抬起头来，平民！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Was machst du? Kopf hoch, Bauernjunge!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Relève la tête, prolétaire ! Où est-ce que tu te crois ?"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP10_ACT1_INTERLUDE3@37#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 425
L37_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "PRINCE_KNIGHT_NULL_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "C"
L38_1 = "어서 검을 잡아라! 알렌 경이 추모를 부탁하더냐!"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "早く剣を取れ！　アレンは自分を悼むよう頼んだか！"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Wield your sword, now! Sir Allen did not ask you to mourn!"
L37_1.m_Talk_ENG = L38_1
L38_1 = "拿起你的劍！艾倫卿要求你悼念了嗎！"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เหวี่ยงดาบซะ! เซอร์อัลเลนไม่ได้ขอให้เจ้ามาคร่ำครวญนะ!"
L37_1.m_Talk_THA = L38_1
L38_1 = "Hãy vung kiếm lên mà chiến đấu! Ngài Allen không cần cậu khóc than!"
L37_1.m_Talk_VTN = L38_1
L38_1 = "拿起你的剑！艾伦爵士要求你悼念了吗！"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Beeil dich und schnapp dir dein Schwert! Sir Allen hat dich nicht darum gebeten, um ihn zu trauern!"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Sire Allen ne t'a pas demandé de le pleurer, si ? Dégaine ton épée !"
