L44_1.m_StartFXSoundName = L45_1
L45_1 = "NEHEMOTH_NPC_NULL_NULL"
L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "C"
L45_1 = "구도자의 방계치고는 제법이었다."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "求道者の傍系にしては、悪くない実力だった。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "That was quite impressive, coming from mere collateral of the Seeker of Truth."
L44_1.m_Talk_ENG = L45_1
L45_1 = "以求道者的旁系來說，你還算不錯。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "น่าประทับใจทีเดียว สำหรับผู้สืบทอดของผู้แสวงสัจจะธรรมดาคนหนึ่ง"
L44_1.m_Talk_THA = L45_1
L45_1 = "Quả thực rất ấn tượng, dù mi vốn chỉ là bàng hệ của Người Tìm Kiếm Sự Thật."
L44_1.m_Talk_VTN = L45_1
L45_1 = "以求道者的旁系来说，你还算不错。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Das war ziemlich beeindruckend, wenn man bedenkt, dass es sich nur um einen Nachfahren des Suchers der Wahrheit handelt."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Pour un rejeton du Chercheur de vérité, je dois dire que tu t'es bien battu."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "EP10_ACT1_INTERLUDE3@45#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 45
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 425
