L46_1 = "NEHEMOTH_NPC_NULL_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "C"
L46_1 = "하지만 너희의 피에 흐르는 것이 얼마나 역겨운 악취를 풍기는지는 몰랐던 모양이군."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "だが、その身に流れる血がどれほどひどい悪臭を放っているかは知らなかったようだな。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Little did you know that what flows in your bloodline reeks of stench."
L45_1.m_Talk_ENG = L46_1
L46_1 = "不過你好像不知道，你們血液中流淌的東西散發著多麼難聞的惡臭。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "เจ้าช่างไม่รู้เลยว่าสิ่งที่ไหลเวียนอยู่ในสายเลือดตนมันส่งกลิ่นเหม็นโชยเพียงใด"
L45_1.m_Talk_THA = L46_1
L46_1 = "Mi chẳng biết rằng thứ chảy trong huyết quản của mi dậy mùi hôi thối."
L45_1.m_Talk_VTN = L46_1
L46_1 = "不过你好像不知道，你们血液中流淌的东西散发着多么难闻的恶臭。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Aber ich schätze, du wusstest nicht, wie widerlich der Gestank des Blutes ist, das durch deine Adern fließt."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Mais tu sembles ignorer l'étendue de la puanteur qui émane de ton sang."
L45_1.m_Talk_FRA = L46_1
