L49_1 = "평민…… 아직, 늦지 않았다…… 너라도……"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "平民……まだ、間に合う……貴様だけでも……"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Peasant... It's not too late... You..."
L48_1.m_Talk_ENG = L49_1
L49_1 = "平民……還，來得及……只要你……"
L48_1.m_Talk_TWN = L49_1
L49_1 = "เจ้าไพร่... ตอนนี้ยังไม่สาย... เจ้า..."
L48_1.m_Talk_THA = L49_1
L49_1 = "Nông dân... Vẫn chưa muộn đâu…Cậu..."
L48_1.m_Talk_VTN = L49_1
L49_1 = "平民……还，不算晚……只要你……"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Bauernjunge ... Es ist noch nicht zu spät ... Du ..."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Vite, prolétaire... il n'est pas encore trop tard... !"
