L2_1 = "EP10_ACT1_INTERLUDE3@51#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 51
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 425
