L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "NEHEMOTH_NPC_NULL_NULL"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "C"
L2_1 = "무력한 양 떼 속에 파묻혀 지내느라 자기 본분을 잊었나, 구원자."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "非力な羊の群れに長く埋もれていたせいで、自分が誰かを忘れてしまったのか、救世主。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Did you forget your true self, Savior? Being surrounded by these helpless lambs?"
L1_1.m_Talk_ENG = L2_1
L2_1 = "在軟弱無力的羊群中生活久了，你忘記自己的本分了嗎，救贖者。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ลืมตัวตนที่แท้จริงของเจ้าไปแล้วหรือไร พระผู้ไถ่เอ๋ย? เพียงเพราะอยู่ท่ามกลางเหล่าลูกแกะที่ช่วยเหลือตัวเองไม่ได้พวกนี้?"
L1_1.m_Talk_THA = L2_1
L2_1 = "Mi đã quên mất con người thực sự của mình rồi sao, Đấng Cứu Thế? Mi đã lạc lối vì bị bao quanh bởi những con cừu vô dụng này sao?"
L1_1.m_Talk_VTN = L2_1
L2_1 = "在软弱无力的羊群中生活久了，你忘记自己的本分了吗，救赎者。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Hast du dein wahres Ich vergessen, Erlöser? Weil du von einer Herde hilfloser Schafe umgeben warst?"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Aurais-tu oublié ta mission à force d'être entouré par ces brebis farouches, Sauveur ?"
