L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "C"
L3_1 = "그 제복은 오직 이 세계에 선택 받은 자만이 갖춰 입을 수 있는 것."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "その礼装は、この世界で選ばれし者だけが着られるものだ。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "That uniform is only given to those who are chosen by this world."
L2_1.m_Talk_ENG = L3_1
L3_1 = "只有被這個世界選中的人才能擁有並穿上那套制服。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "เครื่องแบบนั่นจะมอบให้ก็แต่เพียงผู้ที่จักรวาลนี้เลือกเท่านั้น"
L2_1.m_Talk_THA = L3_1
L3_1 = "Bộ đồ đó chỉ được trao cho những người được thế giới này lựa chọn."
L2_1.m_Talk_VTN = L3_1
L3_1 = "只有被这个世界选中的人才能拥有并穿上那套制服。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Diese Uniform kann nur von den Auserwählten dieser Welt getragen werden."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Cet uniforme que tu portes... il appartient aux élus de ce monde."
L2_1.m_Talk_FRA = L3_1
