L4_1 = "NEHEMOTH_NPC_NULL_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L4_1 = "늑대가 사라진 지금, 마왕을 무찌를 권리는 이 세계에서 오직 너에게만 허락된 것이다."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "狼が消えた今、魔王を倒すことはこの世界でたった一人、そなただけに許されている。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "With the Wolf gone, you are the sole being in this world who is capable of defeating the Demon Lord."
L3_1.m_Talk_ENG = L4_1
L4_1 = "現在狼消失了，這個世界就只剩你擁有打敗魔王的權利。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เมื่อหมาป่าจากไปแล้ว เจ้าก็คือสิ่งมีชีวิตหนึ่งเดียวในโลกนี้ ที่สามารถเอาชนะเจ้าแห่งดีม่อนได้"
L3_1.m_Talk_THA = L4_1
L4_1 = "Khi Con Sói biến mất, ngươi là sinh vật duy nhất trên thế giới này có khả năng đánh bại Chúa Quỷ."
L3_1.m_Talk_VTN = L4_1
L4_1 = "现在狼消失了，这个世界就只剩你拥有打败魔王的权利。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Jetzt, da der Wolf verschwunden ist, hast nur du auf dieser Welt das Recht, den Dämonenfürsten zu besiegen."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Maintenant que la louve n'est plus, tu es le seul qui peut encore vaincre le Seigneur démon."
L3_1.m_Talk_FRA = L4_1
