L7_1[L8_1] = true
L8_1 = "쓰러진 너를 데리고 도망치려 했다."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "倒れたそなたを背負って逃げようとしたのだ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "She tried to run away, carrying you while you were unconscious."
L7_1.m_Talk_ENG = L8_1
L8_1 = "你在說那個試圖帶你逃跑的女人嗎？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "นางพยายามจะหนี แบกเจ้าที่หมดสติอยู่ไปด้วย"
L7_1.m_Talk_THA = L8_1
L8_1 = "Cô ta đã cố gắng mang theo ngươi chạy trốn trong khi ngươi bất tỉnh."
L7_1.m_Talk_VTN = L8_1
L8_1 = "你在说那个试图带你逃跑的女人么。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Sie hat versucht wegzulaufen und trug dich, während du bewusstlos warst."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Quand tu as perdu conscience, elle t'a pris sur les épaules et elle a essayé de s'enfuir."
L7_1.m_Talk_FRA = L8_1
