L8_1[L9_1] = true
L9_1 = "마지막에는 날 섬길 테니 구원자를 살려 달라고 빌다가 내 목을 노리더군."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "最後には我に忠誠を誓う代わりに救世主の助命を請うふりをし、我を殺そうとした。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "She swore to serve me, begging me to spare you... then she came for my throat."
L8_1.m_Talk_ENG = L9_1
L9_1 = "她發誓侍奉我，求我饒你一命，結果卻突然跳起來，企圖砍下我的腦袋。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "นางสาบานจะรับใช้ข้า ขอให้ข้าไว้ชีวิตเจ้า... จากนั้นก็หวังบั่นคอข้า"
L8_1.m_Talk_THA = L9_1
L9_1 = "Cô ta đã thề phục vụ ta, cầu xin ta tha mạng cho ngươi...rồi sau đó lại kề dao vào cổ ta."
L8_1.m_Talk_VTN = L9_1
L9_1 = "她发誓侍奉我，求我饶你一命，结果却突然跳起来，妄图砍下我的脑袋。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Sie schwor mir zu dienen und flehte mich an, dich zu verschonen, aber dann kam sie, um mir die Kehle aufzuschneiden."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Dans ces derniers instants, elle a juré de me servir si je te laissais la vie sauve... avant de me sauter à la gorge."
L8_1.m_Talk_FRA = L9_1
