L9_1[L10_1] = true
L10_1 = "그래서 베었다. 비굴하고 추한 본성을 지닌 여자였어."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "だから斬り捨てた。卑屈で醜い本性を持つ女だった。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "So I killed her. A fool and a coward she was."
L9_1.m_Talk_ENG = L10_1
L10_1 = "所以我殺了她，那個本性卑賤骯髒的女人。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ข้าจึงฆ่านางเสีย ให้สาสมแก่ความโง่งมและขลาดเขลานั้น"
L9_1.m_Talk_THA = L10_1
L10_1 = "Vậy nên ta đã giết cô ta. Quả là một kẻ ngốc và hèn nhát."
L9_1.m_Talk_VTN = L10_1
L10_1 = "所以我杀了她，那个本性卑贱肮脏的女人。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Also habe ich sie stattdessen aufgeschlitzt. Sie war eine feige Närrin."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Alors je l'ai tuée. Ce n'était qu'une imbécile, doublée d'une lâche."
L9_1.m_Talk_FRA = L10_1
