L23_1.m_Talk_THA = L24_1
L24_1 = "Hiền nhân không cảnh báo cho ngươi sao? Thế giới này không đủ sức chứa ngươi đâu."
L23_1.m_Talk_VTN = L24_1
L24_1 = "贤者不是给过你忠告了吗？这个世界太不成熟，无法支撑你。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Hat der Weise dich nicht gewarnt? Diese Welt ist zu schwach, um dich zu stützen."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Le sage ne t'a-t-il pas mis en garde ? Ce monde est trop faible pour te contenir."
