L31_1 = "틀렸어. 간신히 움직임을 따라잡았는데……. 저쪽은 여유가 넘쳐."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "ダメだ。こっちは動きについていくのがやっとだっていうのに……向こうは余裕だ。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "This isn't going to work. I can barely keep up with him... and he’s not tired at all."
L30_1.m_Talk_ENG = L31_1
L31_1 = "從他從容的動作看，就這麼……結束了嗎。我勉強才能跟上……"
L30_1.m_Talk_TWN = L31_1
L31_1 = "แบบนี้ไม่ไหวแน่ เราตามมันแทบไม่ทัน... แถมมันยังไม่เหนื่อยสักนิด"
L30_1.m_Talk_THA = L31_1
L31_1 = "Không ổn chút nào. Mình không thể động vào vạt áo của hắn ta.... và hắn ta chẳng biết mệt mỏi."
L30_1.m_Talk_VTN = L31_1
L31_1 = "从他从容的动作看，就这么……结束了吗。我勉强才能跟上……"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Das wird nicht funktionieren. Ich kann kaum mit ihm mithalten... und er ist überhaupt nicht erschöpft."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Ça ne marche pas. J'arrive à peine à tenir le rythme et lui... on dirait qu'il s'amuse..."
L30_1.m_Talk_FRA = L31_1
