L33_1 = "아니, 어쩌면…… 처음부터 이길 수 없는 싸움이었던 건……"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "いや、もしかすると……初めから勝ち目なんてない戦いだったんじゃ……"
L32_1.m_Talk_JPN = L33_1
L33_1 = "No, maybe... this was a fight meant to be lost..."
L32_1.m_Talk_ENG = L33_1
L33_1 = "不，或許……從一開始這就是一場註定贏不了的戰鬥嗎……"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ไม่สิ บางที... นี่อาจเป็นการต่อสู้ที่ต้องแพ้แต่แรกก็ได้..."
L32_1.m_Talk_THA = L33_1
L33_1 = "Không, có lẽ... cuộc chiến này đã định là phải thua..."
L32_1.m_Talk_VTN = L33_1
L33_1 = "不，或许……从一开始这就是一场注定赢不了的战斗吗……"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Nein, vielleicht ... war dieser Kampf von Anfang an dazu bestimmt, verloren zu werden ..."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Et si... et si ma défaite était déjà écrite ?"
