L35_1 = "……你終究還是無法超越我啊。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "...เจ้ามิอาจเหนือกว่าข้าสินะ"
L34_1.m_Talk_THA = L35_1
L35_1 = "...Vậy là ngươi không thể vượt qua được ta."
L34_1.m_Talk_VTN = L35_1
L35_1 = "……你终究还是无法超越我啊。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "... Letztendlich kannst du mich also nicht übertreffen."
L34_1.m_Talk_DEU = L35_1
L35_1 = "... Ainsi, tu ne peux pas me vaincre."
