L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "인구의 8할을 정리해도 이 정도라니. 쓸데없는 피만 보았다."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "人口の8割を始末してもこの程度とは。無駄な血を見た。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "I destroyed 80 percent of your population, and this is it? What useless bloodshed."
L35_1.m_Talk_ENG = L36_1
L36_1 = "哪怕我滅絕了八成的人口，你還是這種水準。簡直就是白費功夫。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ข้าทำลายประชากรของเจ้าไปแล้วกว่า 8 ส่วน แต่ก็แค่นี้เช่นนั้นหรือ? เปลืองเลือดนองเปล่าเสียจริง"
L35_1.m_Talk_THA = L36_1
L36_1 = "Ta đã hủy diệt 80% dân số của đế chế, vậy mà ngươi chỉ biểu hiện được đến thế này thôi sao? Thật vô dụng."
L35_1.m_Talk_VTN = L36_1
L36_1 = "哪怕我灭绝了八成的人口，你还是这种水平。简直就是白费功夫。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Ich habe 80 Prozent deiner Bevölkerung ausgelöscht, und das ist alles, was du drauf hast? Was für ein sinnloses Blutvergießen."
L35_1.m_Talk_DEU = L36_1
L36_1 = "J'ai décimé 80 % de ton peuple, pour ça ? Tant de sang versé inutilement."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP10_ACT1_INTERLUDE3@86#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 86
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 425
