L37_1 = "UNIT_SERIOUS"
L36_1.m_Face = L37_1
L36_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L36_1.m_Pos = "C"
L37_1 = "당신은 왜…… 그런 힘을 가지고도……!"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "あなたはどうして……そこまでの力がありながら……！"
L36_1.m_Talk_JPN = L37_1
L37_1 = "You... Why...! With that much power, why...!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "你……擁有那樣的力量，為什麼……！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "แก... ทำไม...! มีพลังตั้งมากมายขนาดนั้น แล้วทำไม...!"
L36_1.m_Talk_THA = L37_1
L37_1 = "Ngươi... Tại sao...! Với sức mạnh đến mức ấy, tại sao...!"
L36_1.m_Talk_VTN = L37_1
L37_1 = "你……拥有那样的力量，为什么……！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Du ... Warum ... Mit so viel Kraft, warum ...!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "P-Pourquoi... pourquoi fais-tu ça... ?!"
L36_1.m_Talk_FRA = L37_1
