L38_1 = "NEHEMOTH_NPC_NULL_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "C"
L38_1 = "동료들을 잃어 분노하는가, 구원자."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "仲間を失って憤っているのか、救世主。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Does the loss fuel your rage, Savior?"
L37_1.m_Talk_ENG = L38_1
L38_1 = "為失去同伴感到憤怒嗎，救贖者。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ความสูญเสียนั่นทำโทสะเจ้าพลุ่งพล่านหรือพระผู้ไถ่?"
L37_1.m_Talk_THA = L38_1
L38_1 = "Sự mất mát có làm cơn thịnh nộ của ngươi tăng lên không, Đấng Cứu Thế?"
L37_1.m_Talk_VTN = L38_1
L38_1 = "为失去同伴感到愤怒吗，救赎者。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Schürt der Verlust deine Wut, Erlöser?"
L37_1.m_Talk_DEU = L38_1
L38_1 = "La perte d'êtres chers alimente-t-elle ta rage, Sauveur ?"
