L40_1 = "NEHEMOTH_NPC_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "C"
L40_1 = "너의 동료들을 앗아간 나에게 분노하고 있냐는 뜻이다."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "そなたの仲間の命を奪った我に憤っているのかと聞いているのだ。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "I asked if you are furious because I took the lives of your friends."
L39_1.m_Talk_ENG = L40_1
L40_1 = "我在問你，對奪走你同伴生命的我感到憤怒嗎？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ข้าถามว่าเจ้าเดือดดาลด้วยข้าช่วงชิงชีวิตมิตรสหายเจ้าไปเช่นนั้นหรือ?"
L39_1.m_Talk_THA = L40_1
L40_1 = "Ta hỏi ngươi có giận dữ khi bạn bè ngã xuống hay không."
L39_1.m_Talk_VTN = L40_1
L40_1 = "我在问你，对夺走你同伴生命的我感到愤怒吗。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Ich habe gefragt, ob du wütend bist, weil ich deine Freunde beseitigt habe."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Je te demande si le fait que j'ai tué tous tes amis te rend furieux."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "EP10_ACT1_INTERLUDE3@90#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 90
