L40_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L40_1.m_Pos = "C"
L40_1.m_Crash = 15
L41_1 = "그건……! 그건 당연하잖아! 다들 좋은 사람들이었으니까!"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "それは……！　そんなの当たり前だろう！　みんな良い人たちだったんだ！"
L40_1.m_Talk_JPN = L41_1
L41_1 = "That's...! Of course! They were all good people!"
L40_1.m_Talk_ENG = L41_1
L41_1 = "那……！那當然！大家都是好人！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "นั่นมัน...! ก็แน่อยู่แล้วสิ! พวกเขาเป็นคนดีทั้งนั้นนะ!"
L40_1.m_Talk_THA = L41_1
L41_1 = "Đó là...! Tất nhiên rồi! Họ đều là người tốt!"
L40_1.m_Talk_VTN = L41_1
L41_1 = "那……！那当然！大家都是好人！"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Das ist ...! Das ist doch selbstverständlich! Sie waren alle gute Menschen!"
L40_1.m_Talk_DEU = L41_1
L41_1 = "C'est... ! Bien sûr que oui ! Ils ne méritaient pas de mourir !"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
