L42_1.m_Pos = "C"
L42_1.m_Crash = 10
L43_1 = "대체 뭘 위해서 이렇게까지 하는 거야! 어째서!!"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "いったい何のためにここまでするんだ！　どうして！"
L42_1.m_Talk_JPN = L43_1
L43_1 = "What's the point of all this?! Why?!"
L42_1.m_Talk_ENG = L43_1
L43_1 = "你到底為什麼要做出這種事！為什麼！！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ทั้งหมดนี้มันเพื่ออะไร?! ทำไมกัน?!"
L42_1.m_Talk_THA = L43_1
L43_1 = "Tất cả những điều này là sao?! Tại sao chứ?!"
L42_1.m_Talk_VTN = L43_1
L43_1 = "你到底为什么要做出这种事！为什么！！"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Warum zum Teufel machst du das?! Warum nur?!"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Quel est l'intérêt de tout cela ?! Réponds-moi !"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP10_ACT1_INTERLUDE3@93#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 93
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 425
