L44_1 = "NEHEMOTH_NPC_NULL_NULL"
L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "C"
L44_1 = "어리석은 소리. 세계의 멸망은 필연적이다."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "愚問だな。世界の滅亡は必然だ。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Fool. The end is inevitable."
L43_1.m_Talk_ENG = L44_1
L44_1 = "真是愚蠢。世界的滅亡是必然的。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "เจ้าคนโง่เขลาเอ๋ย จุดจบนั้นมิอาจหลีกเลี่ยงหรอก"
L43_1.m_Talk_THA = L44_1
L44_1 = "Đồ ngu. Kết thúc là không thể tránh khỏi."
L43_1.m_Talk_VTN = L44_1
L44_1 = "真是愚蠢。世界的灭亡是必然的。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "So eine schwachsinnige Frage. Die Zerstörung der Welt ist unvermeidlich."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Imbécile. La fin du monde est inévitable."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "EP10_ACT1_INTERLUDE3@94#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 94
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 425
L44_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "NEHEMOTH_NPC_NULL_NULL"
L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "C"
L45_1 = "나를 막는다고 한들, 이 세계에 예정된 멸망은 결국 도래할 테니."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "我を食い止めることができても、この世界には必ず予定された滅亡が到来する。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Even if you succeed in taking me down, this world is bound to be destroyed."
L44_1.m_Talk_ENG = L45_1
L45_1 = "就算你阻止了我，這個世界所定下的滅亡也終將到來。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ต่อให้เจ้าโค่นข้าลงได้ โลกใบนี้ก็มีชะตาต้องถูกทำลายอยู่ดี"
L44_1.m_Talk_THA = L45_1
L45_1 = "Ngay cả khi ngươi hạ gục được ta, thế giới này vẫn tới hồi kết."
L44_1.m_Talk_VTN = L45_1
L45_1 = "就算你阻止了我，这个世界所定下的灭亡也终将到来。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Selbst wenn es dir gelingt, mich zu Fall zu bringen, wird diese Welt zwangsläufig zerstört."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Même si tu parviens à m'arrêter ici, ce monde est destiné à disparaître."
L44_1.m_Talk_FRA = L45_1
