L51_1 = "그녀의 눈에 비친 나도 너와 같이 비참해 보였겠지……."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "彼女の目に映る我もまた、今のそなたのように惨めだったのだろう……"
L50_1.m_Talk_JPN = L51_1
L51_1 = "In her eyes, I would have looked as pitiful as you look right now..."
L50_1.m_Talk_ENG = L51_1
L51_1 = "她眼中的我，應該也和你一樣悲慘吧……"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ในสายตานาง ข้าคงดูน่าสังเวชเยี่ยงเจ้า ณ ยามนี้เป็นแน่"
L50_1.m_Talk_THA = L51_1
L51_1 = "Trong mắt cô ta, hẳn trông ta đáng thương y như ngươi bây giờ..."
L50_1.m_Talk_VTN = L51_1
L51_1 = "她眼中的我，应该也和你一样悲惨吧……"
L50_1.m_Talk_SCN = L51_1
L51_1 = "In ihren Augen hätte ich genauso erbärmlich ausgesehen, wie du jetzt aussiehst ..."
L50_1.m_Talk_DEU = L51_1
L51_1 = "À ses yeux, je devais avoir l'air aussi pathétique que toi en cet instant."
L50_1.m_Talk_FRA = L51_1
