L4_1 = "NEHEMOTH_NPC_NULL_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L4_1 = "진정으로 네가 동료들을 잃었다는 사실에 분노한다면."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "心からそなたの仲間の死に憤っているのなら。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "If you truly are enraged at the loss of your beloved ones..."
L3_1.m_Talk_ENG = L4_1
L4_1 = "如果你真的為失去同伴感到憤怒。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "หากการสูญเสียบุคคลอันเป็นที่รักไปทำให้เจ้าเดือดดาลยิ่งจริงแล้วละก็"
L3_1.m_Talk_THA = L4_1
L4_1 = "Nếu ngươi thực sự tức giận vì mất đi những người thân yêu của mình..."
L3_1.m_Talk_VTN = L4_1
L4_1 = "如果你真的为失去同伴感到愤怒。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Wenn du wirklich so erzürnt darüber bist, dass du deine Kameraden verloren hast, dann ..."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Si c'est vraiment la perte de ceux que tu aimes qui nourrit ta rage..."
L3_1.m_Talk_FRA = L4_1
