L8_1 = "도발하는 건가? 아니면, 조롱하려고?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "挑発しているのか？　それとも、からかっているのか？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Are you taunting me? Is this mockery?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "你這是在挑釁我嗎？還是在諷刺我？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "นี่แกยั่วโมโหผมเหรอ? จะล้อเลียนกันรึไง?"
L7_1.m_Talk_THA = L8_1
L8_1 = "Ngươi đang chế nhạo ta ư? Đang nhạo báng ta sao?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "你这是在挑衅我吗？还是在讽刺我？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Willst du mich provozieren? Oder dich über mich lustig machen?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "De la provocation ? Tu te moques de moi ?"
L7_1.m_Talk_FRA = L8_1
