L14_1.m_Talk_ENG = L15_1
L15_1 = "究竟是怎麼回事？所以你想死嗎？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "แล้วยังไง? เกิดจะอยากตายขึ้นมาแล้วรึไง?"
L14_1.m_Talk_THA = L15_1
L15_1 = "Vậy thì sao? Giờ ngươi lại muốn chết ư?"
L14_1.m_Talk_VTN = L15_1
L15_1 = "究竟是怎么回事？所以你想死吗？"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Was zum Teufel soll das heißen? Du willst also sterben?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Qu'est-ce que ça veut dire ? Tu veux mourir, maintenant ?"
L14_1.m_Talk_FRA = L15_1
