L15_1[L16_1] = true
L16_1 = "그럼 처음부터 죽어 버리면 됐잖아!"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "なら最初から死ねばよかったじゃないか！"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Then why didn't you just let yourself die in the first place?!"
L15_1.m_Talk_ENG = L16_1
L16_1 = "那你一開始就去死就好了！"
L15_1.m_Talk_TWN = L16_1
L16_1 = "งั้นทำไมไม่ยอมตายๆ ไปซะแต่แรกล่ะ?!"
L15_1.m_Talk_THA = L16_1
L16_1 = "Vậy tại sao ngay từ đầu ngươi không chết luôn đi?!"
L15_1.m_Talk_VTN = L16_1
L16_1 = "那你一开始就去死就好了！"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Warum hast du dich dann nicht von Anfang an direkt töten lassen?!"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Si c'était le cas, pourquoi ne pas l'avoir fait plus tôt ?!"
L15_1.m_Talk_FRA = L16_1
