L17_1 = "m_bCharPinup"
L16_1[L17_1] = true
L17_1 = "세계의 규칙은 네 상상보다 편협하기 때문이지."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "世界のルールはそなたが思うより融通が利かないからだ。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Because the rules of the world are far more biased than you can imagine."
L16_1.m_Talk_ENG = L17_1
L17_1 = "呵呵呵呵……世界的規則比你想像得要狹隘，救贖者。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "เพราะกฎแห่งจักรวาลนั้นลำเอียงเกินกว่าเจ้าจะนึกจินตนาการได้อย่างไรเล่า"
L16_1.m_Talk_THA = L17_1
L17_1 = "Bởi vì các quy luật của thế giới có sự thiên vị, không như ngươi tưởng tượng đâu."
L16_1.m_Talk_VTN = L17_1
L17_1 = "呵呵呵呵……世界的规则比你想象得要狭隘，救赎者。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Weil die Regeln dieser Welt weitaus voreingenommener sind, als du es dir vorstellen kannst."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Parce que les règles de ce monde sont bien plus simples que tu ne l'imagines."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
