L18_1 = "m_bCharPinup"
L17_1[L18_1] = true
L18_1 = "가령, 나를 죽였을 때 네가 마왕의 위계를 계승하는 것처럼."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "例えば、そなたが我を殺したあかつきには魔王の位階を継承するようにな。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Such as the fact that you will assume the title of Demon Lord once you defeat me."
L17_1.m_Talk_ENG = L18_1
L18_1 = "就像，殺死我時，你會繼承魔王的位階一樣。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "เช่น กับข้อเท็จจริงว่า เมื่อเอาชนะข้าได้แล้ว เจ้าก็จะได้เป็นเจ้าแห่งดีม่อนคนต่อไป"
L17_1.m_Talk_THA = L18_1
L18_1 = "Ví dụ như việc ngươi sẽ nhận lấy danh hiệu Chúa Quỷ sau khi đánh bại ta."
L17_1.m_Talk_VTN = L18_1
L18_1 = "就像，杀死我时，你会继承魔王的位阶一样。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Wenn du mich zum Beispiel tötest, erbst du den Titel des Dämonenfürsten."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Et en me tuant, tu deviendras un Seigneur démon à ma place."
L17_1.m_Talk_FRA = L18_1
