L22_1 = "EP10_ACT1_INTERLUDE3@121#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 121
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 425
L21_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "NEHEMOTH_NPC_NULL_NULL"
L21_1.m_CharStrID = L22_1
L22_1 = "빛이 있으면 그림자가 지듯이, 마왕의 위계 역시 이 망가진 세계를 지탱하는 근간 중 하나."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "光があれば影ができるように、魔王の位階もまた、この壊れた世界を支える根幹のひとつ。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "With light comes darkness. The Demon Lord is also one of the pillars that maintain the balance of this world."
L21_1.m_Talk_ENG = L22_1
L22_1 = "就像有光就有暗影一樣，魔王的位階也是支撐這個破敗世界的根基之一。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "เพราะมีแสงสว่างจึงมีความมืดมิด ความมืดมิดเองก็เป็นหนึ่งในเสาหลักที่ช่วยดำรงสมดุลให้จักรวาลนี้เช่นกัน"
L21_1.m_Talk_THA = L22_1
L22_1 = "Có ánh sáng, thì cũng phải có bóng tối. Chúa Quỷ cũng là một trong những trụ cột duy trì sự cân bằng của vũ trụ này."
L21_1.m_Talk_VTN = L22_1
L22_1 = "既然有光那么就有暗影，魔王的位阶也是支撑这个破败的世界的根基之一。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Wo Licht ist, ist auch Schatten. Der Dämonenfürst ist auch eine der Säulen, die das Gleichgewicht dieser Welt aufrechterhalten."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Avec la lumière vient l'obscurité. Les Seigneurs démons sont des êtres essentiels. Des piliers qui maintiennent l'équilibre de ce monde, qui l'empêchent de s'effondrer."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "EP10_ACT1_INTERLUDE3@122#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 122
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 425
L22_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "NEHEMOTH_NPC_NULL_NULL"
L22_1.m_CharStrID = L23_1
L23_1 = "한 세계의 기대를 짊어진 대적자가 아니라면 감당할 재목은 없다."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "一つの世界の期待を背負った敵対者以外、担える者はいない。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "No one will be able to bear the weight, if not for the Antagonist praised by the whole world."
L22_1.m_Talk_ENG = L23_1
L23_1 = "只有背負一個世界期待的敵對者才能勝任。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ผู้ใดก็มิอาจแบกรับความหนักหนานั้นได้ หากไม่ใช่ผู้เป็นปรปักษ์ที่ทั่วทั้งโลกาต่างสรรเสริญ"
L22_1.m_Talk_THA = L23_1
L23_1 = "Không một ai có thể gánh nổi sức nặng của vũ trụ, nếu không có Kẻ Chống Đối mà cả thế giới ca tụng."
L22_1.m_Talk_VTN = L23_1
L23_1 = "但唯有背负一个世界期待的敌对者才能胜任。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Niemand wird in der Lage sein, die Last zu ertragen, wenn es nicht den von der ganzen Welt gepriesenen Antagonisten gäbe."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Car personne, à part l'Antagoniste attendu de tous, ne peut en supporter le poids."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "EP10_ACT1_INTERLUDE3@123#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 123
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 425
L23_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L24_1 = "아까부터 허무맹랑한 소리나 늘어 놓기나 하고!"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "さっきからでたらめばかり言って！"
L23_1.m_Talk_JPN = L24_1
L24_1 = "You're rambling nonsense!"
L23_1.m_Talk_ENG = L24_1
L24_1 = "從剛才開始，你就一直在胡說八道！"
L23_1.m_Talk_TWN = L24_1
L24_1 = "พูดจาเหลวไหลไร้สาระ!"
L23_1.m_Talk_THA = L24_1
L24_1 = "Ngươi đang càm ràm vớ vẩn!"
L23_1.m_Talk_VTN = L24_1
L24_1 = "从刚才开始，你就一直在胡说八道！"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Das ist doch kompletter Schwachsinn!"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Tu mens ! Tout ceci n'est qu'un tissu d'inepties !"
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "EP10_ACT1_INTERLUDE3@124#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 124
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 425
L24_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "RAY_SCHOOL_NPC_B"
L25_1 = "내가 마왕이 된다고? 협박이라도 하려는 거야?"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "僕が魔王になるだって？　それは脅しのつもりか？"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Me becoming the Demon Lord? Are you trying to threaten me or something?"
L24_1.m_Talk_ENG = L25_1
L25_1 = "我會成為魔王？你是想威脅我嗎？"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ผมจะกลายเป็นเจ้าแห่งดีม่อนงั้นเหรอ? นี่พยายามจะขู่กันหรืออะไร?"
L24_1.m_Talk_THA = L25_1
L25_1 = "Ta mà trở thành Chúa Quỷ sao? Ngươi đang định dọa nạt ta ư?"
L24_1.m_Talk_VTN = L25_1
L25_1 = "我会成为魔王？你是想威胁我吗？"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Ich werde der Dämonenfürst? Soll das eine Art Drohung sein?"
L24_1.m_Talk_DEU = L25_1
L25_1 = "Moi, un Seigneur démon ? C'est une menace, n'est-ce pas ?"
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "EP10_ACT1_INTERLUDE3@125#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 125
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 425
L25_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "NEHEMOTH_NPC_NULL_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "마왕의 위계를 계승한다면."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "魔王の位階を継承すれば。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "If you take on the role..."
L25_1.m_Talk_ENG = L26_1
L26_1 = "繼承魔王的階位。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "หากได้รับบทบาทนั้น..."
L25_1.m_Talk_THA = L26_1
L26_1 = "Nếu đảm nhận vai trò..."
L25_1.m_Talk_VTN = L26_1
L26_1 = "继承魔王的位阶。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Wenn du die Rolle des Dämonenfürsten übernimmst ..."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Si tu acceptes d'endosser ce rôle..."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP10_ACT1_INTERLUDE3@126#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 126
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 425
L26_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "NEHEMOTH_NPC_NULL_NULL"
L26_1.m_CharStrID = L27_1
L27_1 = "동료들만은 되살릴 수 있다."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "仲間だけは生き返らせることができよう。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "You can bring your people back to life."
L26_1.m_Talk_ENG = L27_1
L27_1 = "就能救活你的那些同伴。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "เจ้าจะคืนชีพให้ทุกคนได้"
L26_1.m_Talk_THA = L27_1
L27_1 = "Ngươi có thể hồi sinh người của mình."
L26_1.m_Talk_VTN = L27_1
L27_1 = "就能复活你的那些同伴。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Dann kannst du deine Freunde wieder zum Leben erwecken."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Alors tu pourras ramener tes compagnons, et même ton peuple tout entier, à la vie."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP10_ACT1_INTERLUDE3@127#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 425
L27_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "NEHEMOTH_NPC_NULL_NULL"
L27_1.m_CharStrID = L28_1
L28_1 = "너희들이 심복이라고 부르던 나의 동료들처럼."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "そなたらが側近と呼んでいた我の仲間のようにな。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Like my soldiers, whom you have been calling my henchmen."
L27_1.m_Talk_ENG = L28_1
L28_1 = "就像你們稱之為心腹的我的同伴一樣。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ดุจดังเหล่าทหารของข้า ที่พวกเจ้าเรียกว่าลูกสมุน"
L27_1.m_Talk_THA = L28_1
L28_1 = "Giống như những người lính của ta, những kẻ mà ngươi gọi là tay sai."
L27_1.m_Talk_VTN = L28_1
L28_1 = "就像你们称之为心腹的我的同伴一样。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Genau wie meine Soldaten, die ihr als meine Handlanger bezeichnet habt."
L27_1.m_Talk_DEU = L28_1
L28_1 = "De la même façon que je l'ai fait pour mes soldats, ceux que tu appelles mes sbires."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "EP10_ACT1_INTERLUDE3@128#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
