L32_1 = "EP10_ACT1_INTERLUDE3@131#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 425
L31_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "FX_COMBAT_ALL_FOOT_STEP_LANDING_BIG"
L31_1.m_StartFXSoundName = L32_1
L32_1 = "NEHEMOTH_NPC_NULL_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "물론 그 대가로 너는 저들에게 크나큰 증오를 사겠지."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "もちろんその代償として、そなたはあの者たちから多くの憎しみを買うだろう。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Of course, they will despise you. A price to pay for bringing them back."
L31_1.m_Talk_ENG = L32_1
L32_1 = "當然，其代價是你被他們深深地憎恨。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "แต่แน่นอนว่า พวกเขาจะชิงชังเจ้า นั่นอย่างไรสิ่งที่เจ้าต้องแลกกับการพาพวกเขากลับมา"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tất nhiên, chúng sẽ khinh bỉ ngươi. Đó là cái giá phải trả để mang chúng trở lại."
L31_1.m_Talk_VTN = L32_1
L32_1 = "当然，其代价是你被他们深深地憎恨。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Natürlich werden sie dich dafür verachten. Ein Preis, der gezahlt werden muss, um jemanden wieder ins Leben zurückzuholen."
L31_1.m_Talk_DEU = L32_1
L32_1 = "En contrepartie, tu t'attireras la haine partout autour de toi."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EP10_ACT1_INTERLUDE3@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 425
L32_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "NEHEMOTH_NPC_NULL_NULL"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "C"
L33_1 = "나 역시 한때는 그 증오를 짊어질 자신이 있었지만……"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "我もまた、かつてはその憎しみを背負っていく自信があったが……"
L32_1.m_Talk_JPN = L33_1
L33_1 = "There was a time when I thought I was capable of handling the hatred..."
L32_1.m_Talk_ENG = L33_1
L33_1 = "曾經我也有信心背負那種憎恨……"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ครั้งหนึ่งข้าก็เคยคิดว่าตัวเองจะรับมือกับการเป็นที่ชิงชังได้..."
L32_1.m_Talk_THA = L33_1
L33_1 = "Đã có lúc ta nghĩ mình chịu được sự thù hận..."
L32_1.m_Talk_VTN = L33_1
L33_1 = "曾经我也有信心背负那种憎恨……"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Es gab eine Zeit, in der ich dachte, ich wäre in der Lage, mit dem Hass umzugehen ..."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Pour ma part, j'ai longtemps cru que j'arriverais à vivre avec cette haine..."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "EP10_ACT1_INTERLUDE3@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 425
L33_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "NEHEMOTH_NPC_NULL_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "결국 모두 만용에 불과했다."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "結局のところ、すべては蛮勇に過ぎなかった。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "But I was mistaken."
L33_1.m_Talk_ENG = L34_1
L34_1 = "但到頭來全都只是我的匹夫之勇而已。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "แต่ข้าเข้าใจผิดไปถนัด"
L33_1.m_Talk_THA = L34_1
L34_1 = "Nhưng ta đã nhầm."
L33_1.m_Talk_VTN = L34_1
L34_1 = "但到头来全都只是我的匹夫之勇而已。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Aber ich habe mich geirrt."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Mais je m'étais trompé."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP10_ACT1_INTERLUDE3@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 425
L34_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "NEHEMOTH_NPC_NULL_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "그럼에도 원한다면 마왕의 위계를 계승해라, 구원자."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "それでもなお望むなら、魔王の位階を継承しろ、救世主。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "If you are still willing to save your people, be the successor to this role, Savior."
L34_1.m_Talk_ENG = L35_1
L35_1 = "哪怕如此你也願意的話，那就繼承魔王的階位吧，救贖者。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "หากเจ้ายังเต็มใจจะช่วยพวกพ้องตน ก็จงรับสืบทอดบทบาทนี้ไปเถิด พระผู้ไถ่เอ๋ย"
L34_1.m_Talk_THA = L35_1
L35_1 = "Nếu mi vẫn sẵn lòng cứu sống bạn bè mình, hãy kế nhiệm vai trò này. Đấng Cứu Thế."
L34_1.m_Talk_VTN = L35_1
L35_1 = "哪怕如此你也愿意的话，那就继承魔王的位阶吧，救赎者。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Wenn du bereit bist, diese Last auf dich zu nehmen, dann werde der nächste Dämonenfürst, Erlöser."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Si tu veux sauver ton peuple... tu dois devenir le Seigneur démon, Sauveur."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
