L38_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "구원자님께서 우리를 지켜 주신다! 이제 우리 모두 살았어!"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "救世主様が守ってくださる！　我々は皆助かるんだ！"
L38_1.m_Talk_JPN = L39_1
L39_1 = "The Savior protected us! We are saved!"
L38_1.m_Talk_ENG = L39_1
L39_1 = "有救贖者大人保護我們！現在我們都有救了！"
L38_1.m_Talk_TWN = L39_1
L39_1 = "พระผู้ไถ่ปกป้องเราไว้! พวกเราปลอดภัยแล้ว!"
L38_1.m_Talk_THA = L39_1
L39_1 = "Đấng Cứu Thế đã bảo vệ chúng ta! Chúng ta được cứu rồi!"
L38_1.m_Talk_VTN = L39_1
L39_1 = "有救赎者保护我们！现在我们都有救了！"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Der Erlöser hat uns beschützt! Wir sind gerettet!"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Le Sauveur nous a protégés ! Nous sommes sauvés !"
L38_1.m_Talk_FRA = L39_1
