L41_1 = "UNIT_LAUGH"
L40_1.m_Face = L41_1
L41_1 = "HOLY_KNIGHT_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "C"
L41_1 = "구원의 맹세를 기억하세요."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "救いの誓いを思い出してください。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Remember the oath of salvation."
L40_1.m_Talk_ENG = L41_1
L41_1 = "請記住救贖的誓言。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "อย่าได้ลืมสัจจะแห่งการไถ่บาป"
L40_1.m_Talk_THA = L41_1
L41_1 = "Hãy ghi nhớ lời thề cứu thế."
L40_1.m_Talk_VTN = L41_1
L41_1 = "请记住救赎之誓。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Erinnere dich an den Eid der Erlösung."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Rappelez-vous votre serment."
L40_1.m_Talk_FRA = L41_1
