L42_1 = "HOLY_KNIGHT_NULL_NULL"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "C"
L42_1 = "구원자님께서는 꼭 이 세계를 구해 주실 겁니다. 저를 구원해 주셨듯이."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "救世主様は必ずこの世界を救ってくださいます。私を救ってくださったように。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "You will save our world, Savior. Just as you have saved me."
L41_1.m_Talk_ENG = L42_1
L42_1 = "救贖者大人一定會拯救這個世界，就像曾經救贖我那樣。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ท่านได้ช่วยโลกของเราไว้นะคะ พระผู้ไถ่ เฉกเช่นได้ช่วยชีวิตข้า"
L41_1.m_Talk_THA = L42_1
L42_1 = "Anh sẽ cứu rỗi thế giới của chúng ta, Đấng Cứu Thế à. Cũng giống như anh đã cứu tôi."
L41_1.m_Talk_VTN = L42_1
L42_1 = "救赎者大人您一定会拯救这个世界，就像曾经救赎我那样。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Du wirst unsere Welt retten, Erlöser. So wie du auch mich gerettet hast."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Vous sauverez notre monde, Sauveur. J'en suis convaincue. Tout comme vous m'avez sauvée, moi."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
