L44_1 = "EP10_ACT1_INTERLUDE3@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 425
L43_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "정말 마왕과 싸워 이길 수 있는 걸까……?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "本当に魔王と戦って勝てるのか……？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Can we really win against the Demon Lord...?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "我們真的能戰勝魔王嗎……？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "เราจะเอาชนะเจ้าแห่งดีม่อนได้จริงๆ เหรอ...?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Liệu chúng ta có thể thực sự chiến thắng được Chúa Quỷ không...?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "我们真的能战胜魔王吗……？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Können wir wirklich gegen den Dämonenfürsten gewinnen ...?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "On peut vraiment gagner contre le Seigneur démon... ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "EP10_ACT1_INTERLUDE3@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 425
L44_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "구원자님이 계신다면 가능할 거야! 내가 전쟁터에서 이 두 눈으로 직접 봤거든!"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "救世主様がいてくださればできる！　戦場でこの目で直接見たんだ！"
L44_1.m_Talk_JPN = L45_1
L45_1 = "With the Savior by our side, I'm sure we can! I saw him in battle, with my own eyes!"
L44_1.m_Talk_ENG = L45_1
L45_1 = "有救贖者大人在就能！我在戰場上親眼看到了！"
L44_1.m_Talk_TWN = L45_1
L45_1 = "พระผู้ไถ่อยู่ข้างเราทั้งคน เราต้องทำได้สิ! ข้าเห็นเขาสู้มากับตาเลยนะ!"
L44_1.m_Talk_THA = L45_1
L45_1 = "Khi có Đấng Cứu Thế ở bên cạnh chúng ta, tôi chắc rằng chúng ta có thể! Tôi đã tận mắt thấy ngài ấy trong trận chiến!"
L44_1.m_Talk_VTN = L45_1
L45_1 = "有救赎者在就能！我在战场上亲眼看到了！"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Mit dem Erlöser an unserer Seite können wir das bestimmt schaffen! Ich habe ihn mit eigenen Augen auf dem Schlachtfeld gesehen!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Avec le Sauveur à nos côtés, ça ne fait aucun doute ! J'ai vu ses prouesses au combat de mes propres yeux !"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
