L47_1 = "EP10_ACT1_INTERLUDE3@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 425
L46_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "UNIT_PRIDE"
L46_1.m_Face = L47_1
L47_1 = "PRINCE_KNIGHT_NULL_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "C"
L47_1 = "흠. 이제 와서 그 제복의 무게를 실감한 거냐, 평민. 여전히 미숙하군."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "ふむ。今になってやっとその礼装の重みを実感したのか、平民。相変わらずの未熟さだ。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Hmm. So you finally realized what you've gotten yourself into, peasant. So naive."
L46_1.m_Talk_ENG = L47_1
L47_1 = "哼，現在你終於切身感受到那套制服的重量了，平民。不過還是不熟練啊。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "อืม ในที่สุดก็รู้แล้วสินะเจ้าไพร่ ว่าพาตัวเองไปพัวพันกับอะไรเข้า ช่างไร้เดียงสาเสียจริง"
L46_1.m_Talk_THA = L47_1
L47_1 = "Hmm. Vậy là cuối cùng cậu cũng nhận ra mình đã dính vào cái gì rồi, Nhóc Nông Dân à. Cậu ngây thơ quá."
L46_1.m_Talk_VTN = L47_1
L47_1 = "哼，现在你终于切身感受到那套制服的重量了，平民。不过还是不熟练啊。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Hmm. Ist dir jetzt bewusst geworden, wie schwer die Last dieser Uniform ist, Bauernjunge? Du bist noch immer so unreif."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Hmm. Alors ça y est, tu réalises enfin le prix de ta décision ? Quelle naïveté."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EP10_ACT1_INTERLUDE3@147#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 147
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 425
L47_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "PRINCE_KNIGHT_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L48_1 = "네가 구원자의 길을 걷는 것이 아니다. 철지난 전설 따위에 목매달 셈인가?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "貴様が救世主の道を踏襲するのではない。あの古い伝説などにしがみついてどうする？"
L47_1.m_Talk_JPN = L48_1
L48_1 = "It is not that you are walking the path of the Savior. Don't get hung up on an old myth."
L47_1.m_Talk_ENG = L48_1
L48_1 = "並不是你走在救贖者之路上。那只不過是老掉牙的傳說罷了。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "มันไม่ใช่ว่าเจ้ากำลังเดินอยู่บนเส้นทางของการเป็นพระผู้ไถ่เสียหน่อย อย่าไปยึดติดกับเรื่องปรัมปรานักเลย"
L47_1.m_Talk_THA = L48_1
L48_1 = "Không phải cậu đang đi trên con đường của một Đấng Cứu Thế đâu. Đừng có quá tin vào những lời đồn đãi xưa cũ."
L47_1.m_Talk_VTN = L48_1
L48_1 = "并不是你走在救赎者之路上。那只不过是老掉牙的传说罢了。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Es ist schließlich nicht so, dass du den Weg des Erlösers gehst. Klammere dich also nicht so an einem alten Mythos fest."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Ne t'accroches pas à ces vieilles coutumes, prolétaire. Tu ne suis pas la voie du Sauveur."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "EP10_ACT1_INTERLUDE3@148#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 425
L48_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "PRINCE_KNIGHT_NULL_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "그러니, 네가 걷는 길을 구원자의 길로 만들어라."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "だから、貴様の歩む道を救世主の道としろ。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "You shall make the path you walk into the path of the Savior."
L48_1.m_Talk_ENG = L49_1
L49_1 = "你要明白，是你走的路，才稱之為救贖者之路。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "แต่เจ้าต้องสร้างเส้นทางสู่การเป็นพระผู้ไถ่ด้วยตนเอง"
L48_1.m_Talk_THA = L49_1
L49_1 = "Cậu phải tự tạo ra con đường trở thành Đấng Cứu Thế của chính mình."
L48_1.m_Talk_VTN = L49_1
L49_1 = "你要明白，是你走的路，才称之为救赎者之路。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Du sollst den Weg, den du gehst, zum Weg des Erlösers machen."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Au contraire, c'est la voie que tu crées qui deviendra celle du Sauveur."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
