L50_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "구원자님 만세! 전하 만세!"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "救世主様万歳！　殿下万歳！"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Long live the Savior! Long live His Highness!"
L50_1.m_Talk_ENG = L51_1
L51_1 = "救贖者大人萬歲！殿下萬歲！"
L50_1.m_Talk_TWN = L51_1
L51_1 = "พระผู้ไถ่จงเจริญ! ฝ่าบาทจงเจริญ!"
L50_1.m_Talk_THA = L51_1
L51_1 = "Đấng Cứu Thế muôn năm! Điện Hạ vạn tuế!"
L50_1.m_Talk_VTN = L51_1
L51_1 = "救赎者万岁！殿下万岁！"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Lang lebe der Erlöser! Lang lebe Eure Hoheit!"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Vive le Sauveur ! Vive Son Altesse !"
L50_1.m_Talk_FRA = L51_1
