L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "부디 무사히 돌아오세요! 매일 기도드릴게요!"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "無事にお帰りください！　毎日お祈りします！"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Please come back safe! We will pray for you every day!"
L1_1.m_Talk_ENG = L2_1
L2_1 = "請一定要平安回來！我們會每天祈禱的！"
L1_1.m_Talk_TWN = L2_1
L2_1 = "โปรดกลับมาอย่างปลอดภัยด้วย! พวกเราจะภาวนาให้ทุกวัน!"
L1_1.m_Talk_THA = L2_1
L2_1 = "Xin hãy bình an trở lại! Chúng tôi sẽ cầu nguyện cho ngài mỗi ngày!"
L1_1.m_Talk_VTN = L2_1
L2_1 = "请一定要平安回来！我们会每天祈祷的！"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Bitte kehren Sie unbeschadet zurück! Wir werden jeden Tag für Sie beten!"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Puissiez-vous trouver le chemin de la victoire ! Nous prierons tous les jours pour votre retour !"
L1_1.m_Talk_FRA = L2_1
