L4_1 = "UNIT_SERIOUS"
L3_1.m_Face = L4_1
L4_1 = "CHARLOTTE_ORDER_NULL_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L4_1 = "언젠가는 반드시 널 넘어서겠어. 구원자."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "いつの日か必ずそなたを越えてみせる。救世主。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Someday, I swear I will beat you. Savior."
L3_1.m_Talk_ENG = L4_1
L4_1 = "總有一天我要超越你，救贖者。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ข้าสาบานเลยค่ะ ว่าสักวันจะเอาชนะท่านให้ได้ พระผู้ไถ่"
L3_1.m_Talk_THA = L4_1
L4_1 = "Một ngày nào đó, tôi thề mình sẽ đánh bại cậu. Đấng Cứu Thế."
L3_1.m_Talk_VTN = L4_1
L4_1 = "总有一天我要超过你，救赎者。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Eines Tages werde ich dich auf jeden Fall übertreffen, Erlöser."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Je te battrai un jour, Sauveur. J'en fais le serment."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "EP10_ACT1_INTERLUDE3@154#Talk"
