L5_1 = "CHARLOTTE_ORDER_NULL_NULL"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "C"
L5_1 = "그러니 그 때까지는 살아 있어야 해."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "だから、その時までは生きていろ。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "So make sure you stay alive until then."
L4_1.m_Talk_ENG = L5_1
L5_1 = "所以，你一定要活到那個時候。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ดังนั้น ท่านต้องมีชีวิตอยู่จนถึงตอนนั้นให้ได้นะคะ"
L4_1.m_Talk_THA = L5_1
L5_1 = "Vì vậy, hãy chắc chắn rằng đến lúc đó cậu vẫn còn thở nhé."
L4_1.m_Talk_VTN = L5_1
L5_1 = "所以，你一定要活到那个时候。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Also musst du bis dahin unbedingt am Leben bleiben."
L4_1.m_Talk_DEU = L5_1
L5_1 = "D'ici là, tu dois rester en vie."
L4_1.m_Talk_FRA = L5_1
