L7_1 = "EP10_ACT1_INTERLUDE3@156#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 156
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 425
L6_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "KNIGHT_NPC_NULL_NULL"
L7_1 = "구원자님께서 와 주신 덕분에 아무도 부상을 입지 않았습니다!"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "救世主様が来てくださったおかげで、誰も怪我をせずに済みました！"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Thanks to you, Savior, no one was hurt!"
L6_1.m_Talk_ENG = L7_1
L7_1 = "托救贖者大人的福，這次沒有一個人受傷！"
L6_1.m_Talk_TWN = L7_1
L7_1 = "เพราะท่านทีเดียวพระผู้ไถ่ จึงไม่มีใครบาดเจ็บเลย!"
L6_1.m_Talk_THA = L7_1
L7_1 = "Nhờ có ngài, Đấng Cứu Thế, không ai bị thương cả!"
L6_1.m_Talk_VTN = L7_1
L7_1 = "因为救赎者，这次没有一个人受伤！"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Dank Ihnen wurde niemand verletzt, Erlöser!"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Grâce à vous, nous sommes tous rentrés sains et saufs !"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "EP10_ACT1_INTERLUDE3@157#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 157
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 425
L7_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "KNIGHT_NPC_NULL_NULL"
L8_1 = "감사합니다, 구원자님! 덕분에 가족들과 다시 만날 수 있게 됐어요!"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "ありがとうございます、救世主様！　おかげさまで家族とまた会えます！"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Thank you, Savior! If it wasn't for you, I wouldn't have been able to reunite with my family!"
L7_1.m_Talk_ENG = L8_1
L8_1 = "謝謝您，救贖者大人！多虧了您，我們才能再次見到家人！"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ขอบคุณครับพระผู้ไถ่! ถ้าไม่ได้ท่าน ข้าคงไม่ได้กลับมาเจอหน้าครอบครัวแล้ว!"
L7_1.m_Talk_THA = L8_1
L8_1 = "Cảm ơn ngài, Đấng Cứu Thế! Nếu không có ngài, tôi đã không thể đoàn tụ với gia đình mình!"
L7_1.m_Talk_VTN = L8_1
L8_1 = "谢谢您，救赎者！多亏了您，我们才能再次见到家人！"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Vielen Dank, Erlöser! Ohne Sie wäre ich nicht in der Lage gewesen, meine Familie wiederzusehen!"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Merci, Sauveur ! Sans vous, je n'aurais jamais revu ma famille !"
L7_1.m_Talk_FRA = L8_1
