L9_1.m_Pos = "C"
L10_1 = "설령 이 세상에 구원이란 게 없더라도……"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "たとえこの世界に救いというものが無かったとしても……"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Even if there is no such thing as salvation in this world..."
L9_1.m_Talk_ENG = L10_1
L10_1 = "沒錯，就算世界上沒有所謂的救贖……"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ต่อให้โลกนี้ไม่มีอะไรอย่างการไถ่บาป..."
L9_1.m_Talk_THA = L10_1
L10_1 = "Ngay cả khi không có thứ gọi là cứu rỗi cho thế giới này..."
L9_1.m_Talk_VTN = L10_1
L10_1 = "就算这个世界也已经没有所谓的救赎了……"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Auch wenn es für diese Welt keine Erlösung gibt ..."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Même si ce monde est voué à disparaître..."
L9_1.m_Talk_FRA = L10_1
