L18_1 = "네헤모트! 네헤모트는 어떻게 되었나!"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "ネヘモト！　ネヘモトはどうなった！"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Nehemoth! What happened to Nehemoth?"
L17_1.m_Talk_ENG = L18_1
L18_1 = "貝赫莫特！貝赫莫特呢！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "นีฮีมอท! แล้วนีฮีมอทล่ะ?"
L17_1.m_Talk_THA = L18_1
L18_1 = "Nehemoth! Điều gì đã xảy ra với Nehemoth thế?"
L17_1.m_Talk_VTN = L18_1
L18_1 = "涅赫摩斯！涅赫摩斯呢！"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Nehemoth! Was ist mit Nehemoth passiert?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Nehemoth ! Où est passé Nehemoth ?"
L17_1.m_Talk_FRA = L18_1
