L19_1 = "진정하시죠, 전하. 네헤모트는 이 곳에 없습니다."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "落ち着いてください、殿下。ネヘモトはここにはいません。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Calm down, Your Highness. Nehemoth is not here."
L18_1.m_Talk_ENG = L19_1
L19_1 = "請冷靜點，殿下。貝赫莫特不在這裡。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ใจเย็นก่อนนะครับฝ่าบาท นีฮีมอทไม่อยู่แล้ว"
L18_1.m_Talk_THA = L19_1
L19_1 = "Điện Hạ hãy bình tĩnh. Nehemoth không ở đây."
L18_1.m_Talk_VTN = L19_1
L19_1 = "请冷静点，殿下。涅赫摩斯不在这里。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Beruhigt Euch, Eure Hoheit. Nehemoth ist nicht hier."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Calmez-vous, Votre Altesse. Nehemoth n'est pas là."
