L20_1 = "뭐라? 그렇다면 그 평민이 해냈다고?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "なに？　ならばあの平民がやったのか？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "What? Are you saying that the peasant did it?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "什麼？那個平民做到了？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "หา? จะบอกว่าฝีมือเจ้าไพร่นั่นรึ?"
L19_1.m_Talk_THA = L20_1
L20_1 = "Cái gì? Ngài đang nói là Nhóc Nông Dân đã làm được sao?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "什么？那个平民做到了？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Was? Willst du damit sagen, dass dieser Bauernjunge ihn erledigt hat?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Comment ? Tu veux dire que ce prolétaire l'a vaincu... ?"
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "EP10_ACT1_INTERLUDE3@170#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 170
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 425
L20_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "UNIT_DESPAIR"
L20_1.m_Face = L21_1
L21_1 = "PRINCE_KNIGHT_NULL_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "C"
L21_1 = "……아니, 무언가 이상하지 않느냐. 알렌 경."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "……いや、何かがおかしいと思わないか。アレン。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "...No, that's not it. Something feels strange, Sir Allen."
L20_1.m_Talk_ENG = L21_1
L21_1 = "……不，你不覺得有種奇怪的感覺嗎，艾倫卿。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "...ไม่ ไม่ใช่สิ มันมีอะไรแปลกๆ นะเซอร์อัลเลน"
L20_1.m_Talk_THA = L21_1
L21_1 = "...Không, không phải vậy đâu. Có gì lạ lắm, Ngài Allen ạ."
L20_1.m_Talk_VTN = L21_1
L21_1 = "……不，你不觉得有种奇怪的感觉吗，艾伦爵士。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "... Nein. Irgendwas stimmt hier nicht, Sir Allen."
L20_1.m_Talk_DEU = L21_1
L21_1 = "... Non ce n'est pas ça. Vous ne trouvez pas ça bizarre, Sire Allen ?"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "EP10_ACT1_INTERLUDE3@171#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 171
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 425
L21_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "PRINCE_KNIGHT_NULL_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "C"
L22_1 = "그대도 나와 같이 죽음이 임박했다고 느꼈을 것이다."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "そなたも私と同じく、死を目前に感じていたはずだ。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "I know you felt that death was upon you, just like I did."
L21_1.m_Talk_ENG = L22_1
L22_1 = "你應該也和我一樣，有瀕臨死亡的感覺吧。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ข้ารู้ว่าเจ้ารู้สึกว่าเกือบตายไปแล้ว เช่นเดียวกับข้า"
L21_1.m_Talk_THA = L22_1
L22_1 = "Tôi biết ngài đã cảm thấy mình chết đi, giống như tôi lúc nãy."
L21_1.m_Talk_VTN = L22_1
L22_1 = "你应该也和我一样，有濒临死亡的感觉吧。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Du musst, genau wie ich, gespürt haben, dass der Tod unmittelbar bevorstand."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Vous l'avez senti vous aussi, n'est-ce pas ? L'étreinte glaciale de la faucheuse..."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "EP10_ACT1_INTERLUDE3@172#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 172
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 425
L22_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Face = "UNIT_HATE"
L23_1 = "PRINCE_KNIGHT_NULL_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "C"
L23_1 = "하지만 지금은 뭔가 다르다. 오히려……"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "しかし、今は何かが違う。むしろ……"
L22_1.m_Talk_JPN = L23_1
L23_1 = "But something is different now. It's rather..."
L22_1.m_Talk_ENG = L23_1
L23_1 = "但是現在有什麼不一樣了，反而……"
L22_1.m_Talk_TWN = L23_1
L23_1 = "แต่ตอนนี้มันแปลกๆ มันออกจะ..."
L22_1.m_Talk_THA = L23_1
L23_1 = "Nhưng bây giờ, có gì đó rất khác. Nó giống như..."
L22_1.m_Talk_VTN = L23_1
L23_1 = "但是现在有什么不一样了，反而……"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Aber irgendetwas ist jetzt anders. Es ist eher ..."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Et pourtant, on dirait que quelque chose a changé."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "EP10_ACT1_INTERLUDE3@173#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 173
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 425
L23_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "UNIT_DESPAIR"
L23_1.m_Face = L24_1
L23_1.m_CharStrID = "ALLEN_ORDER_NULL_NULL"
L23_1.m_Pos = "C"
L24_1 = "……자신의 것이 아닌 힘이 몸 속에 흐르는 기분이시군요."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "……自分のものではない、何かしらの力が体内に流れている感覚でしょうか。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "...You feel a surge of power flowing inside you, a power that is not yours."
L23_1.m_Talk_ENG = L24_1
L24_1 = "……有種不是自己的力量在身體裡流淌的感覺。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "...ท่านรู้สึกว่ามีพลังพลุ่งพล่านไหลอยู่ในร่างใช่มั้ยครับ พลังที่ไม่ใช่ของท่าน"
L23_1.m_Talk_THA = L24_1
L24_1 = "…Ngài cảm thấy một sức mạnh trào dâng từ bên trong, một sức mạnh không phải là của ngài."
L23_1.m_Talk_VTN = L24_1
L24_1 = "……有种不是自己的力量在身体里流淌的感觉。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "... Ihr habt das Gefühl, als ob eine Kraft, die nicht Euch gehört, durch Euren Körper fließt."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Je sens une puissance incroyable couler dans mes veines. Une puissance qui n'est pas la mienne..."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
