L24_1.m_fTalkTime = 0.03
L25_1 = "私も同じです。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "I feel the same, Your Highness."
L24_1.m_Talk_ENG = L25_1
L25_1 = "我也這麼覺得。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ผมเองก็รู้สึกเหมือนกันครับฝ่าบาท"
L24_1.m_Talk_THA = L25_1
L25_1 = "Tôi cũng cảm thấy như vậy, thưa Điện Hạ."
L24_1.m_Talk_VTN = L25_1
L25_1 = "我这么觉得。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Mir geht es genauso, Eure Hoheit."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Oui, moi aussi."
