L29_1 = "EP10_ACT1_INTERLUDE3@178#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 178
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 425
L28_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "HOLY_KNIGHT_NULL_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "R"
L29_1 = "구원자님……? 부활의 지팡이도 빼앗겼을 텐데, 이게 어떻게 된 일이죠?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "救世主様……？　復活の杖も奪われたのに、どうなっているのですか？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Savior...? What happened? The Demon Lord took the Staff of Resurrection..."
L28_1.m_Talk_ENG = L29_1
L29_1 = "救贖者大人……？復活之杖被搶走了！……怎麼會這樣？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "พระผู้ไถ่คะ...? เกิดอะไรขึ้น? เจ้าแห่งดีม่อนชิงคทาแห่งการฟื้นคืนชีพไปหรือคะ?"
L28_1.m_Talk_THA = L29_1
L29_1 = "Đấng Cứu Thế...? Chuyện gì đã xảy ra vậy? Chúa Quỷ đã lấy được Quyền Trượng Phục Sinh..."
L28_1.m_Talk_VTN = L29_1
L29_1 = "救赎者大人……？复活权杖被抢走了！……哎？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Erlöser ...? Was passiert? Der Dämonenfürst hat mir den Stab der Wiederbelebung gestohlen. Wie konnte das passieren?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Sauveur... ? Comment est-ce possible ? Le Seigneur démon s'était emparé du Sceptre de la Renaissance, pourtant..."
L28_1.m_Talk_FRA = L29_1
