L37_1 = "殿下、落ち着いてください！"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Your Highness! Wait–"
L36_1.m_Talk_ENG = L37_1
L37_1 = "殿下，請您冷靜點！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ฝ่าบาท! เดี๋ยวก่อน–"
L36_1.m_Talk_THA = L37_1
L37_1 = "Điện Hạ! Xin chờ đã-"
L36_1.m_Talk_VTN = L37_1
L37_1 = "殿下，请您冷静点！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Eure Hoheit, beruhigt Euch doch!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Calmez-vous, Votre Altesse !"
