L45_1 = "YOOMINA_FENRIR_NEXT_NULL"
L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "L"
L44_1.m_Crash = 10
L45_1 = "중간부터 갑자기 레이 선배가 된 것 같았어……. 어떻게 된 거야? "
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "途中からまるで自分がレイ先輩になったような気分だったよ……いったいどうなってるの？ "
L44_1.m_Talk_JPN = L45_1
L45_1 = "I felt as if I was Ray midway through... What happened?"
L44_1.m_Talk_ENG = L45_1
L45_1 = "我看到一半的時候，感覺自己突然變成雷伊前輩了……這是怎麼回事？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ฉันรู้สึกเหมือนตัวเองกลายเป็นเรย์ไปครึ่ง... นี่มันเกิดอะไรขึ้นน่ะ?"
L44_1.m_Talk_THA = L45_1
L45_1 = "Đột nhiên tôi cảm thấy như mình là Ray... Chuyện gì đã xảy ra vậy?"
L44_1.m_Talk_VTN = L45_1
L45_1 = "我看到一半的时候，感觉自己突然变成雷伊前辈了……这是怎么回事？ "
L44_1.m_Talk_SCN = L45_1
L45_1 = "Ich hatte mittendrin das Gefühl, als würde ich zu Ray werden ... Was ist passiert?"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Qu'est-ce qui s'est passé... ? À l'instant, c'est comme si ma conscience avait fusionné avec celle de Ray !"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
