L47_1 = "EP10_ACT1_INTERLUDE3@196#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 196
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 425
L46_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "JOOSHIYOON_FENRIR_CA_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "C"
L47_1 = "네. 느끼셨던 그대로입니다. 확실히 아슬아슬했어요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "はい、お感じになった通りです。今のは危なかったですよ。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "You felt it right. It was close."
L46_1.m_Talk_ENG = L47_1
L47_1 = "呼，就是你感覺到的那樣。確實很驚險。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "อย่างที่เธอรู้สึกแหละ เกือบไปแล้ว"
L46_1.m_Talk_THA = L47_1
L47_1 = "Cô cảm nhận đúng đấy. Suýt chút nữa thì."
L46_1.m_Talk_VTN = L47_1
L47_1 = "呼，就是你感觉到的那样。确实很惊险。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Ja. Es ist genau so, wie du es empfunden hast. Das war echt knapp."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Oui, c'est exactement ce qui s'est passé. On l'a échappée belle."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EP10_ACT1_INTERLUDE3@197#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 197
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 425
L47_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "JOOSHIYOON_FENRIR_CA_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L48_1 = "마지막에는 저희 모두 환각을 일으킨 장본인의 의식에 삼켜질 뻔했거든요."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "最後は僕たち全員が幻覚を引き起こした張本人の意識に呑み込まれかけましたからね。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "We almost got devoured by the consciousness of whoever made this hallucination."
L47_1.m_Talk_ENG = L48_1
L48_1 = "最後我們差點被製造這個幻覺的罪魁禍首的意識給吞噬了呢。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "เราเกือบโดนสติสัมปชัญญะของใครก็ไม่รู้ที่สร้างภาพหลอนนี่ขึ้นมากลืนกินไปแล้ว"
L47_1.m_Talk_THA = L48_1
L48_1 = "Chúng ta gần như bị ý thức của kẻ đã tạo ra ảo giác này nuốt chửng."
L47_1.m_Talk_VTN = L48_1
L48_1 = "最后我们差点被制造这个幻觉的罪魁祸首的意识所吞噬了呢。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Wir wurden fast von dem Bewusstsein der Person verschlungen, die diese Halluzination verursacht hat."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Cette hallucination collective... elle a failli nous priver de notre propre conscience pour de bon."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "EP10_ACT1_INTERLUDE3@198#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 198
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 425
L48_1.m_CutScenStrID = "EP10_ACT1_INTERLUDE3"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "JOOSHIYOON_FENRIR_CA_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "저희가 상당히 과하게 몰입하길 바라셨나 보네요. <color=#ffd34c>네헤모트</color> 씨."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "僕たちが過度にのめり込むのを願っていたみたいですね。<color=#ffd34c>ネヘモト</color>さん。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "It seems like you wanted us to be immersed, <color=#ffd34c>Mr. Nehemoth</color>."
L48_1.m_Talk_ENG = L49_1
L49_1 = "這就是你的意圖嗎，<color=#ffd34c>貝赫莫特</color>？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "เหมือนคุณอยากให้พวกเราจมลงไปเลยนะครับ <color=#ffd34c>คุณนีฮีมอท</color>"
L48_1.m_Talk_THA = L49_1
L49_1 = "Có vẻ như ngươi đã muốn chúng ta bị lung lạc, <color=#ffd34c>Quý Ngài Nehemoth</color> ạ."
L48_1.m_Talk_VTN = L49_1
L49_1 = "这就是你的意图吗，<color=#ffd34c>涅赫摩斯</color>？"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Es ​​scheint, als ob Sie wollten, dass wir in Ihre Gedanken eintauchen, <color=#ffd34c>Nehemoth</color>."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Une technique d'immersion pour le moins remarquable, <color=#ffd34c>Nehemoth</color>."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
