L51_1 = "……我不是有意如此。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "...ผมไม่ได้ตั้งใจครับ"
L50_1.m_Talk_THA = L51_1
L51_1 = "...Tôi không cố ý đâu."
L50_1.m_Talk_VTN = L51_1
L51_1 = "……我不是有意如此。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "... Das war nicht meine Absicht."
L50_1.m_Talk_DEU = L51_1
L51_1 = "... Ce n'était pas mon intention."
